PRETRAIN = '"""Tiny fixed-budget pretraining harness. One file.\n\nModel: small GPT (nanoGPT-style). Data: a fixed token budget from FineWeb-edu (or TinyStories), tokenized once with\nthe GPT-2 tokenizer and cached. Trains for a given number of unique tokens x epochs. Reports held-out loss over time\nand (optionally) a controlled knowledge probe: synthetic facts inserted into the stream with a chosen number of\nexposures each, then tested by completion accuracy. Designed so any "mechanism" is a small diff on top.\n"""\nimport argparse, json, math, os, time, random\nimport numpy as np, torch, torch.nn as nn, torch.nn.functional as F\n\nDEV = "cuda" if torch.cuda.is_available() else ("mps" if torch.backends.mps.is_available() else "cpu")\nCACHE = "/tmp/se_tokens"\n\n\n# ---------------- data ----------------\ndef get_tokens(source, n_tokens, seed=0):\n    os.makedirs(CACHE, exist_ok=True); path = f"{CACHE}/{source}_{n_tokens}.npy"\n    if os.path.exists(path): return np.load(path)\n    from datasets import load_dataset\n    import tiktoken\n    enc = tiktoken.get_encoding("gpt2")\n    if source == "fineweb": ds = load_dataset("HuggingFaceFW/fineweb-edu", "sample-10BT", split="train", streaming=True)\n    elif source == "tinystories": ds = load_dataset("roneneldan/TinyStories", split="train", streaming=True)\n    else: raise ValueError(source)\n    out = []\n    for x in ds:\n        out.extend(enc.encode_ordinary(x["text"]) + [enc.eot_token])\n        if len(out) >= n_tokens + 200_000: break\n    arr = np.array(out[:n_tokens + 200_000], dtype=np.uint16); np.save(path, arr); return arr\n\n\nclass Facts:\n    """One invented town. Every resident has a surname (families), a job at a named shop on a named street, a spouse\n    within the town, and a pet. Facts are stated as plain sentences; each resident\'s facts appear `k` times in the\n    stream (k drawn from `exposures`, balanced). Probes: direct recall (job / street / spouse / pet given the name) and\n    composition (the spouse\'s street, never stated in one sentence). Names are ordinary but the combinations are new."""\n    FIRST = ["Mara", "Tomas", "Ilse", "Ruben", "Nell", "Corin", "Dagny", "Piet", "Sunna", "Wendel", "Orla", "Bastian", "Livia", "Anselm", "Greta", "Hollis", "Ines", "Jorah", "Kaia", "Lucan", "Maren", "Nico", "Odile", "Pell", "Quilla", "Rafe", "Sable", "Teodor", "Una", "Viggo", "Wren", "Ysolde", "Zev", "Alba", "Bram", "Cissy", "Dov", "Elke", "Fenn", "Gudrun"]\n    LAST = ["Feld", "Ashby", "Corrin", "Delacroix", "Ember", "Farrow", "Grieve", "Halloran", "Iversen", "Jarl", "Kestrel", "Lindqvist", "Moor", "Nakamura", "Oduya", "Pryce", "Quennell", "Rooke", "Saltram", "Thorne", "Ulland", "Varga", "Wick", "Yarrow", "Zeller"]\n    JOBS = [("baker", "bakery"), ("doctor", "clinic"), ("blacksmith", "forge"), ("librarian", "library"), ("teacher", "school"), ("fisher", "boathouse"), ("tailor", "tailor shop"), ("brewer", "brewery"), ("carpenter", "workshop"), ("florist", "flower shop"), ("butcher", "butcher shop"), ("potter", "pottery"), ("grocer", "grocery"), ("mechanic", "garage"), ("pharmacist", "pharmacy"), ("barber", "barbershop"), ("cobbler", "shoe shop"), ("printer", "print shop"), ("vet", "animal clinic"), ("innkeeper", "inn")]\n    STREETS = ["Elm Street", "Harbor Road", "Mill Lane", "Orchard Way", "Church Street", "Quarry Road", "Willow Lane", "Market Square", "Tannery Row", "Hillcrest Drive", "Foundry Street", "Meadow Lane", "Bridge Street", "Copper Lane", "Station Road", "Ferry Lane"]\n    PETS = ["dog", "cat", "parrot", "goat", "rabbit", "tortoise", "pony", "ferret", "canary", "hen"]\n    PETNAMES = ["Biscuit", "Pepper", "Moss", "Clover", "Tansy", "Rook", "Pudding", "Sorrel", "Bramble", "Fig", "Juniper", "Nutmeg", "Olive", "Pickle", "Quince", "Rusty", "Sage", "Thimble", "Waffle", "Ziggy"]\n\n    def __init__(self, enc, n_facts, exposures, seed=0):\n        rng = random.Random(seed); self.enc = enc; n = n_facts\n        names = list(set((rng.choice(self.FIRST), rng.choice(self.LAST)) for _ in range(n * 4)))[:n]\n        rng.shuffle(names); assert len(names) == n, "not enough distinct names"\n        self.people = []\n        for i, (f, l) in enumerate(names):\n            job, shop = rng.choice(self.JOBS)\n            self.people.append(dict(name=f" {f} {l}", job=job, shop=shop, street=rng.choice(self.STREETS), pet=rng.choice(self.PETS), petname=rng.choice(self.PETNAMES), k=exposures[i % len(exposures)]))\n        # spouses: pair within the same exposure bucket so composition probes are at one exposure level\n        for k in set(p["k"] for p in self.people):\n            grp = [p for p in self.people if p["k"] == k]; rng.shuffle(grp)\n            for a, b in zip(grp[::2], grp[1::2]): a["spouse"] = b; b["spouse"] = a\n        self.items = self.people\n\n    def facts(self, p):\n        return [f"{p[\'name\']} is the {p[\'job\']} and runs the {p[\'shop\']} on {p[\'street\']}.",\n                f"{p[\'name\']} has a {p[\'pet\']} named {p[\'petname\']}."] + \\\n               ([f"{p[\'name\']} is married to{p[\'spouse\'][\'name\']}."] if "spouse" in p else [])\n\n    def sentences(self, paraphrase=False):\n        ctx = ["", " As everyone in town knows,", " According to the town records,", " Ask anyone on the street:", " It is well known that", " The neighbours will tell you that", " In the town register it says", " Everybody agrees that"]\n        out = []\n        for p in self.people:\n            for j in range(p["k"]):\n                for f in self.facts(p): out.append(((ctx[(j + len(f)) % len(ctx)] + " ") if paraphrase else " ") + f)\n        return out\n\n    def _gen_batch(self, model, prompts, block, n=4):\n        """Greedy n tokens for many prompts; grouped by token length so no padding is needed."""\n        outs = {}; enc_p = [(i, self.enc.encode_ordinary(p)) for i, p in enumerate(prompts)]\n        by_len = {}\n        for i, t in enc_p: by_len.setdefault(len(t), []).append((i, t))\n        with torch.no_grad():\n            for L, grp in by_len.items():\n                for s in range(0, len(grp), 256):\n                    chunk = grp[s:s + 256]; ids = torch.tensor([t for _, t in chunk], device=DEV)\n                    for _ in range(n): ids = torch.cat([ids, model(ids[:, -block:])[:, -1].argmax(-1, keepdim=True)], 1)\n                    for (i, _), row in zip(chunk, ids[:, -n:].tolist()): outs[i] = self.enc.decode(row).strip()\n        return [outs[i] for i in range(len(prompts))]\n\n    def probes(self, p):\n        """(kind, prompt, answer)"""\n        q = [("job", f"{p[\'name\']} is the", p["job"]), ("street", f"{p[\'name\']} is the {p[\'job\']} and runs the {p[\'shop\']} on", p["street"]),\n             ("pet", f"{p[\'name\']} has a {p[\'pet\']} named", p["petname"]),\n             ("qa_job", f"Question: What does{p[\'name\']} do for a living? Answer:{p[\'name\']} is the", p["job"]),\n             ("qa_street", f"Question: Where is the {p[\'shop\']} run by{p[\'name\']}? Answer: On", p["street"])]\n        if "spouse" in p:\n            q.append(("spouse", f"{p[\'name\']} is married to", p["spouse"]["name"].strip()))\n            # composition: never stated in one sentence\n            q.append(("compose_street", f"The spouse of{p[\'name\']} runs a shop on", p["spouse"]["street"]))\n            q.append(("compose_job", f"The spouse of{p[\'name\']} is the", p["spouse"]["job"]))\n        return q\n\n    def probe(self, model, block, by_exposure=False):\n        model.eval(); qs = [(p, kind, prompt, ans) for p in self.people for kind, prompt, ans in self.probes(p)]\n        gens = self._gen_batch(model, [q[2] for q in qs], block); hit = {}; tot = {}\n        for (p, kind, prompt, ans), g in zip(qs, gens):\n            key = f"{p[\'k\']}:{kind}" if by_exposure else kind\n            hit[key] = hit.get(key, 0) + g.startswith(ans); tot[key] = tot.get(key, 0) + 1\n        model.train(); return {k: round(hit[k] / tot[k], 3) for k in sorted(hit)}\n\n\n# ---------------- model ----------------\nclass Attn(nn.Module):\n    def __init__(self, d, h):\n        super().__init__(); self.h = h; self.qkv = nn.Linear(d, 3 * d); self.proj = nn.Linear(d, d)\n    def forward(self, x):\n        B, T, D = x.shape; q, k, v = self.qkv(x).view(B, T, 3, self.h, D // self.h).permute(2, 0, 3, 1, 4)\n        y = F.scaled_dot_product_attention(q, k, v, is_causal=True); return self.proj(y.transpose(1, 2).reshape(B, T, D))\n\n\nclass Block(nn.Module):\n    def __init__(self, d, h):\n        super().__init__(); self.ln1 = nn.LayerNorm(d); self.attn = Attn(d, h); self.ln2 = nn.LayerNorm(d)\n        self.mlp = nn.Sequential(nn.Linear(d, 4 * d), nn.GELU(), nn.Linear(4 * d, d))\n    def forward(self, x, mask=None):\n        x = x + self.attn(self.ln1(x)); return x + self.mlp(self.ln2(x))\n\n\nclass GPT(nn.Module):\n    def __init__(self, vocab=50304, d=384, layers=6, heads=6, block=256):\n        super().__init__(); self.block = block; self.tok = nn.Embedding(vocab, d); self.pos = nn.Embedding(block, d)\n        self.blocks = nn.ModuleList([Block(d, heads) for _ in range(layers)]); self.ln = nn.LayerNorm(d); self.head = nn.Linear(d, vocab, bias=False)\n        self.head.weight = self.tok.weight\n        self.apply(self._init)\n    @staticmethod\n    def _init(m):\n        if isinstance(m, (nn.Linear, nn.Embedding)): nn.init.normal_(m.weight, std=0.02)\n        if isinstance(m, nn.Linear) and m.bias is not None: nn.init.zeros_(m.bias)\n    def forward(self, idx):\n        T = idx.shape[1]; x = self.tok(idx) + self.pos(torch.arange(T, device=idx.device))\n        for b in self.blocks: x = b(x)\n        return self.head(self.ln(x))\n\n\n# ---------------- train ----------------\n_DEV_CACHE = {}\ndef batches(tokens, block, bs, g, order=None):\n    key = (id(tokens), len(tokens))\n    if key not in _DEV_CACHE: _DEV_CACHE.clear(); _DEV_CACHE[key] = torch.from_numpy(tokens.astype(np.int64)).to(DEV)\n    t = _DEV_CACHE[key]; n = len(tokens) - block - 1; idx = (torch.randperm(n // block, generator=g) if order is None else order) * block\n    ar = torch.arange(block, device=DEV)\n    for i in range(0, len(idx), bs):\n        j = idx[i:i + bs]; x = t[j.to(DEV)[:, None] + ar]; yield x[:, :-1], x[:, 1:], j // block\n\n\n@torch.no_grad()\ndef eval_loss(model, tokens, block, n_batches=20, bs=32):\n    model.eval(); g = torch.Generator().manual_seed(123); tot = 0; n = 0\n    for i, (x, y, _) in enumerate(batches(tokens, block, bs, g)):\n        if i >= n_batches: break\n        tot += F.cross_entropy(model(x).view(-1, model.head.weight.shape[0]), y.reshape(-1)).item(); n += 1\n    model.train(); return tot / n\n\n\ndef main():\n    p = argparse.ArgumentParser()\n    p.add_argument("--source", default="fineweb"); p.add_argument("--tokens", type=int, default=5_000_000); p.add_argument("--epochs", type=int, default=1)\n    p.add_argument("--d", type=int, default=384); p.add_argument("--layers", type=int, default=6); p.add_argument("--block", type=int, default=256)\n    p.add_argument("--bs", type=int, default=32); p.add_argument("--lr", type=float, default=1e-3); p.add_argument("--wd", type=float, default=0.1)\n    p.add_argument("--facts", type=int, default=0); p.add_argument("--exposures", default="1,3,10,30,100"); p.add_argument("--paraphrase", action="store_true")\n    p.add_argument("--mask", type=float, default=0.0, help="fraction of input tokens replaced by <eot> (hidden-text fill); targets unchanged"); p.add_argument("--reshuffle", action="store_true", help="re-splice fact sentences at fresh positions every pass (same sentences, new neighbours)"); p.add_argument("--hard", action="store_true", help="flashcards: from epoch 2 on, reread the half of chunks with highest last loss, twice each (same budget)"); p.add_argument("--seed", type=int, default=0); p.add_argument("--tag", default="run"); p.add_argument("--eval_every", type=int, default=200)\n    a = p.parse_args(); torch.manual_seed(a.seed); random.seed(a.seed)\n    toks = get_tokens(a.source, a.tokens, a.seed); train, held = toks[:a.tokens], toks[a.tokens:]\n    facts = None\n    if a.facts:\n        import tiktoken; enc = tiktoken.get_encoding("gpt2"); facts = Facts(enc, a.facts, [int(e) for e in a.exposures.split(",")], a.seed)\n        sents = facts.sentences(a.paraphrase); encs = [np.array(enc.encode_ordinary(s) + [enc.eot_token], dtype=np.uint16) for s in sents]\n        def splice(seed):\n            """Write each fact sentence at the START of a distinct random 512-token block (offset 0 for every fact, every arm,\n            so position-in-window is never a confound: 2505.13171). Budget fixed: facts overwrite tokens. dup = same blocks\n            every pass; --reshuffle = new blocks (new neighbours) every pass."""\n            t = train_base.copy(); nb = len(t) // a.block; rng = random.Random(seed)\n            blocks = rng.sample(range(nb), len(encs))\n            for b, e in zip(blocks, encs): t[b * a.block: b * a.block + len(e)] = e[:a.block]\n            return t\n        train_base = train[:a.tokens].copy()\n        train = splice(a.seed)\n    model = GPT(d=a.d, layers=a.layers, heads=a.d // 64, block=a.block).to(DEV)\n    nparams = sum(p.numel() for p in model.parameters()) - model.tok.weight.numel()\n    opt = torch.optim.AdamW(model.parameters(), lr=a.lr, weight_decay=a.wd, betas=(0.9, 0.95))\n    steps_per_epoch = (len(train) // a.block) // a.bs; total = steps_per_epoch * a.epochs\n    sched = torch.optim.lr_scheduler.LambdaLR(opt, lambda s: min(1, (s + 1) / 100) * 0.5 * (1 + math.cos(math.pi * min(s, total) / total)))\n    scaler = torch.amp.GradScaler(enabled=DEV == "cuda"); g = torch.Generator().manual_seed(a.seed); log = []; step = 0; t0 = time.time()\n    print(f"{a.tag}: {nparams/1e6:.1f}M non-embedding params, {a.tokens/1e6:.1f}M tokens x {a.epochs} epochs, {total} steps, {DEV}", flush=True)\n    n_chunks = (len(train) - a.block - 1) // a.block; chunk_loss = torch.full((n_chunks,), float("inf"))\n    for ep in range(a.epochs):\n        if facts and a.reshuffle and ep > 0: train = splice(a.seed + 1000 * ep); _DEV_CACHE.clear()\n        order = None\n        if a.hard and ep > 0:  # ponytail: top-half by last loss, each twice; a real spacing schedule if this pays\n            top = chunk_loss.topk(n_chunks // 2).indices; order = top[torch.randperm(len(top), generator=g)].repeat(2)\n        for x, y, cid in batches(train, a.block, a.bs, g, order):\n            if a.mask > 0: x = torch.where(torch.rand(x.shape, device=DEV) < a.mask, torch.full_like(x, 50256), x)\n            with torch.autocast(device_type="cuda", dtype=torch.float16, enabled=DEV == "cuda"):\n                per_tok = F.cross_entropy(model(x).view(-1, model.head.weight.shape[0]).float(), y.reshape(-1), reduction="none").view(y.shape)\n            loss = per_tok.mean(); chunk_loss[cid] = per_tok.detach().mean(1).float().cpu()\n            opt.zero_grad(); scaler.scale(loss).backward(); scaler.unscale_(opt); torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0); scaler.step(opt); scaler.update(); sched.step(); step += 1\n            if step % a.eval_every == 0 or step == total:\n                hl = eval_loss(model, held, a.block); rec = dict(step=step, tokens_seen=step * a.bs * a.block, train=round(loss.item(), 4), held=round(hl, 4), secs=round(time.time() - t0))\n                if facts: rec["fact_acc"] = facts.probe(model, a.block)\n                rec["tok_s"] = round(rec["tokens_seen"] / max(1, rec["secs"])); log.append(rec); print(rec, flush=True)\n    if facts:\n        rec = facts.probe(model, a.block, by_exposure=True); print("fact acc by exposure:kind:", rec, flush=True); log.append(dict(by_exposure=rec))\n    json.dump(dict(args=vars(a), nparams=nparams, log=log), open(f"results_{a.tag}.json", "w"))\n\n\nif __name__ == "__main__":\n    main()\n'

import subprocess, sys, os, json
CFG = {"tag": "law_30m_reshuffle", "args": ["--source", "fineweb", "--tokens", "25000000", "--block", "512", "--bs", "32", "--facts", "600", "--exposures", "1,3,10,30,100", "--eval_every", "1500", "--epochs", "4", "--d", "512", "--layers", "9", "--reshuffle"]}
open("/kaggle/working/pretrain.py","w").write(PRETRAIN)
tag=CFG["tag"]; cmd=[sys.executable,"/kaggle/working/pretrain.py"]+CFG["args"]+["--tag",tag]
print("RUN",tag,cmd,flush=True); subprocess.run(cmd,cwd="/kaggle/working",check=False)
if os.path.exists(f"/kaggle/working/results_{tag}.json"): print("DONE",tag,flush=True)
